import java.util.*;

class Solution {
    public int sawCost(int length, int[] marks) {
        int c = marks.length;
        int[] p = new int[c + 2];
        int[] sorted = marks.clone();
        Arrays.sort(sorted);
        for (int i = 0; i < c; i++) p[i + 1] = sorted[i];
        p[c + 1] = length;                              // endpoints 0 and length
        int n = c + 2;
        int[][] dp = new int[n][n];                     // dp[i][j]: all cuts strictly between p[i] and p[j]
        for (int gap = 2; gap < n; gap++) {
            for (int i = 0; i + gap < n; i++) {
                int j = i + gap, best = Integer.MAX_VALUE;
                for (int m = i + 1; m < j; m++) {       // m is the first cut on this piece
                    best = Math.min(best, dp[i][m] + dp[m][j]);
                }
                dp[i][j] = best + (p[j] - p[i]);        // first cut costs the whole piece
            }
        }
        return dp[0][n - 1];
    }
}

