class Solution:
    def sawCost(self, length: int, marks: List[int]) -> int:
        p = [0] + sorted(marks) + [length]
        n = len(p)
        dp = [[0] * n for _ in range(n)]
        for gap in range(2, n):
            for i in range(n - gap):
                j = i + gap
                dp[i][j] = p[j] - p[i] + min(dp[i][m] + dp[m][j] for m in range(i + 1, j))
        return dp[0][n - 1]

