function sawCost(length, marks) {
  const p = [0, ...[...marks].sort((a, b) => a - b), length], n = p.length;
  const memo = new Map();
  function go(i, j) {
    if (j - i < 2) return 0;
    const key = i * 1000 + j;
    if (memo.has(key)) return memo.get(key);
    let best = Infinity;
    for (let m = i + 1; m < j; m++) best = Math.min(best, go(i, m) + go(m, j));
    best += p[j] - p[i];
    memo.set(key, best);
    return best;
  }
  return go(0, n - 1);
}
